#!/bin/bash
#
# Regenerates compose.yaml and the hostfiles for a cluster of NUM_SEGS real
# segment containers (seg1..segN, one primary + one mirror each).
#
#   ./gen-cluster.sh        # 50 segments (default)
#   NUM_SEGS=10 ./gen-cluster.sh
#
# The generated files are committed, so this only needs to be run to change
# the segment count. Rebuild the image afterwards (make build) -- the
# hostfiles are baked into it.

set -e
cd "$(dirname "$0")"

NUM_SEGS="${NUM_SEGS:-50}"

# --- hostfiles ---------------------------------------------------------
: > hostfile_segments_whpginitsystem7
: > hostfile_whpginitsystem7
printf 'coordinator\nstandby\n' > hostfile_ssh_whpginitsystem7
printf 'coordinator\nstandby\n' > hostfile_whpginitsystem7
for i in $(seq 1 "${NUM_SEGS}"); do
    echo "seg${i}" >> hostfile_segments_whpginitsystem7
    echo "seg${i}" >> hostfile_ssh_whpginitsystem7
    echo "seg${i}" >> hostfile_whpginitsystem7
done
echo "# gpfdist" >> hostfile_ssh_whpginitsystem7

# --- compose.yaml ------------------------------------------------------
{
cat <<'EOF'
# GENERATED by gen-cluster.sh -- edit that script, not this file.
#
# Only the coordinator has a build section; every other service reuses the
# same image (pull_policy: never), so `make build` builds it once instead
# of 52 times.

x-whpg-node: &whpg-node
  restart: unless-stopped
  image: whpg7-50seg-systemd:latest
  pull_policy: never
  secrets:
    - edbtoken_secret
    - edbrepository_secret
  cgroup: host

  # without an allocated pty, /dev/console never gets created inside the
  # container, so ForwardToConsole/StandardOutput=...+console has nowhere
  # to write and `docker logs` stays empty no matter what journald says
  tty: true
  tmpfs:
    - /run
    - /tmp
  stop_signal: SIGRTMIN+3
  stop_grace_period: 60s
  environment:
    - container=docker
  platform: linux/amd64
  networks:
    whpg-sme-network:

services:
  coordinator:
    <<: *whpg-node
    build:
      context: .
      dockerfile: Dockerfile
      secrets:
        - edbtoken_secret
        - edbrepository_secret
    deploy:
      resources:
        limits:
          cpus: 4.0
          memory: 4gb
        reservations:
          cpus: 1.0
          memory: 1gb
    ports:
      - "6470:5432"
      - "18120:8080"
      - "17250:7233"
    volumes:
      - ./data/coordinator/data:/whpgdata
      - /sys/fs/cgroup:/sys/fs/cgroup:rw
    hostname: coordinator

  standby:
    <<: *whpg-node
    deploy:
      resources:
        limits:
          cpus: 2.0
          memory: 2gb
        reservations:
          cpus: 0.5
          memory: 512mb
    ports:
      - "6471:5432"
      - "18121:8080"
      - "18122:8123"
      - "18123:8081"
      - "19010:9000"
    volumes:
      - ./data/standby/data:/whpgdata
      - /sys/fs/cgroup:/sys/fs/cgroup:rw
    hostname: standby
EOF
for i in $(seq 1 "${NUM_SEGS}"); do
cat <<EOF

  seg${i}:
    <<: *whpg-node
    deploy:
      resources:
        limits:
          cpus: 1.0
          memory: 700mb
    volumes:
      - ./data/seg${i}/data:/whpgdata
      - /sys/fs/cgroup:/sys/fs/cgroup:rw
    hostname: seg${i}
EOF
done
cat <<'EOF'

secrets:
  edbtoken_secret:
    environment: EDBTOKEN
  edbrepository_secret:
    environment: EDBREPOSITORY


networks:
  whpg-sme-network:
    driver: bridge
EOF
} > compose.yaml

echo "Generated compose.yaml and hostfiles for ${NUM_SEGS} segments."
